function bossGuideMarkup(){const desc={warden:'Wave 5 miniboss. Winds up, charges your position, then slams the ground.',hollow:'Alternates marked ground blasts with circular projectile volleys.',ember:'Fast pursuit, aimed fire fans, and marked eruptions.',frost:'Aimed crystal volleys mixed with slow radial barrages.'};return `<small>ARENA ENCOUNTERS</small><h2>Meet the bosses.</h2><p>Iron Warden guards wave 5. Wave 10 picks a random major boss. Endless waves 20, 30, 40… rotate through all three without repeating the previous boss.</p><div class="cards" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:16px">${Object.entries(bossRoster).map(([id,b])=>`<div style="padding:14px;border:1px solid ${b.color}66;border-radius:12px;background:#15232b"><canvas id="boss-preview-${id}" width="150" height="135" style="display:block;position:static;width:110px;height:100px;max-width:100%;margin:auto"></canvas><strong style="color:${b.color}">${b.name}</strong><p>${desc[id]}</p><small>${b.mini?'MINIBOSS · WAVE 5':'MAJOR BOSS · WAVE 10 / ENDLESS'}</small></div>`).join('')}</div><p><button id="boss-back">BACK TO MENU</button></p>`}
function paintBossGuide(){for(const [id,b]of Object.entries(bossRoster)){const c=document.querySelector('#boss-preview-'+id)?.getContext('2d');if(c)drawBossBody(c,{x:75,y:75,r:29,bossType:id})}}

const bossRoster={warden:{name:'IRON WARDEN',color:'#c8d49b',hp:1100,r:34,speed:78,damage:18,mini:true},hollow:{name:'HOLLOW KING',color:'#df87b5',hp:5200,r:43,speed:95,damage:28},ember:{name:'EMBER TYRANT',color:'#ff9863',hp:4700,r:44,speed:110,damage:26},frost:{name:'FROST MATRIARCH',color:'#91e5ff',hp:5600,r:41,speed:82,damage:25}};
function bossWaveNumber(w){return w===5||w%10===0}
function pickBoss(owner,w){if(w===5)return 'warden';owner.bossBag=owner.bossBag||[];if(!owner.bossBag.length){owner.bossBag=['hollow','ember','frost'];for(let i=2;i>0;i--){const j=Math.floor(Math.random()*(i+1));[owner.bossBag[i],owner.bossBag[j]]=[owner.bossBag[j],owner.bossBag[i]]}if(owner.bossBag[0]===owner.lastBoss)[owner.bossBag[0],owner.bossBag[1]]=[owner.bossBag[1],owner.bossBag[0]]}const id=owner.bossBag.shift();owner.lastBoss=id;return id}
// Shared encounter patterns: wind up, lock aim, then release. Damage stays authoritative.
function bossMotion(e,target,dt,time,shoot,area){
 const type=e.bossType||'hollow',ang=Math.atan2(target.y-e.y,target.x-e.x),rage=e.hp<e.maxHp*.5;
 if(e.cool<=0&&e.wind<=0&&e.charge<=0){e.cool=type==='warden'?3.8:rage?1.9:2.8;e.phase=(e.phase||0)+1;e.wind=type==='warden'?.8:.65;e.cx=Math.cos(ang);e.cy=Math.sin(ang)}
 if(e.wind>0){e.wind-=dt;if(e.wind<=0){const a=Math.atan2(e.cy,e.cx);
  if(type==='warden'){e.charge=.65}
  else if(type==='hollow'){if(e.phase%2)area(target.x,target.y,85,1,e.damage*1.2);else for(let i=0;i<(rage?14:10);i++)shoot(i*Math.PI*2/(rage?14:10),155)}
  else if(type==='ember'){const n=rage?11:7;for(let i=0;i<n;i++)shoot(a+(i-(n-1)/2)*.16,230);if(e.phase%2===0)area(target.x,target.y,105,.9,e.damage)}
  else {for(let i=-1;i<=1;i++)shoot(a+i*.22,290);if(e.phase%2===0)for(let i=0;i<12;i++)shoot(i*Math.PI/6+time*.15,130)}
 }return {x:0,y:0}}
 if(e.charge>0){e.charge-=dt;if(e.charge<=0)area(e.x,e.y,95,.5,e.damage);return {x:e.cx*390,y:e.cy*390}}
 const d=Math.hypot(target.x-e.x,target.y-e.y)||1,s=e.speed*1.25*(e.slow>0?.5:1);return {x:(target.x-e.x)/d*s,y:(target.y-e.y)/d*s};
}
function drawBossBody(c,e,time=0){const b=bossRoster[e.bossType||'hollow'],r=e.r;c.save();c.translate(e.x,e.y);c.fillStyle='#0005';c.beginPath();c.ellipse(0,r*.8,r*1.2,r*.35,0,0,6.283);c.fill();c.fillStyle=e.flash>0?'#fff':b.color;c.strokeStyle='#172534';c.lineWidth=3;
 const poly=ps=>{c.beginPath();ps.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fill();c.stroke()};
 if(e.bossType==='warden'){poly([[-r,-r*.6],[r,-r*.6],[r*.9,r*.6],[0,r],[-r*.9,r*.6]]);c.fillStyle='#566472';c.fillRect(-r*.55,-r*.65,r*1.1,r*.65);c.fillStyle='#ffe89c';c.fillRect(-r*.4,-r*.35,r*.8,5);c.fillStyle='#899aac';c.fillRect(-r*1.25,-r*.3,r*.38,r*1.1);c.fillRect(r,-r*.1,r*.4,r*.6)}
 else if(e.bossType==='ember'){poly([[-r*.8,r*.7],[-r,-r*.3],[-r*.6,-r*1.2],[-r*.2,-r*.6],[0,-r*1.55],[r*.35,-r*.65],[r*.85,-r*1.15],[r,-r*.2],[r*.7,r*.7]]);c.fillStyle='#632c35';poly([[-r*.5,-r*.2],[0,-r*.7],[r*.5,-r*.2],[r*.35,r*.6],[-r*.35,r*.6]]);c.fillStyle='#fff0a0';poly([[0,-r*.2],[r*.2,r*.25],[0,r*.6],[-r*.2,r*.25]])}
 else if(e.bossType==='frost'){poly([[0,-r*1.3],[r*.85,-r*.3],[r,r*.8],[0,r*.5],[-r,r*.8],[-r*.85,-r*.3]]);c.fillStyle='#d9faff';for(let i=-1;i<=1;i++){const x=i*r*.55;poly([[x,-r*.5],[x-r*.2,-r],[x,-r*1.5],[x+r*.2,-r]])}c.strokeStyle='#eaffff';c.beginPath();c.moveTo(0,-r*.3);c.lineTo(0,r*.5);c.moveTo(-r*.4,0);c.lineTo(r*.4,0);c.stroke()}
 else {poly(Array.from({length:8},(_,i)=>{const a=i*Math.PI/4-Math.PI/2;return [Math.cos(a)*r,Math.sin(a)*r]}));c.fillStyle='#ffe596';poly([[-r*.7,-r*.4],[-r*.9,-r*1.3],[-r*.2,-r*.7],[0,-r*1.5],[r*.2,-r*.7],[r*.9,-r*1.3],[r*.7,-r*.4]])}
 c.fillStyle='#fff4cc';c.fillRect(-r*.4,-4,6,5);c.fillRect(r*.25,-4,6,5);c.restore();
}

const SLOT_STAKES=[15,30,60,120];let selectedSlotStake=30;
function gamblePrice(p,w,gambler,stake=selectedSlotStake){return Math.round(stake*(gambler?.75:1))}
function resolveGamble(p,w,gambler,random=Math.random,loot={},capacity=()=>0,stake=30){
 if(!SLOT_STAKES.includes(stake))return false;const cost=gamblePrice(p,w,gambler,stake);if((p.gambles||0)>=5||p.cash<cost)return false;
 p.cash-=cost;p.gambles=(p.gambles||0)+1;const roll=random(),odds=gambler?[.15,.45,.65,.80,.92]:[.35,.65,.80,.90,.98];
 const kind=roll<odds[0]?'bust':roll<odds[1]?'materials':roll<odds[2]?'upgrade':roll<odds[3]?'weapon':roll<odds[4]?'buff':'jackpot',tier=SLOT_STAKES.indexOf(stake);
 const pick=list=>list[Math.min(list.length-1,Math.floor(random()*list.length))],levelGain=tier===3?2:1;
 p.slotReels={bust:['☠','🍒','⚔'],materials:['✦','✦','✦'],upgrade:['⬆','⬆','⬆'],weapon:['⚔','⚔','⚔'],buff:['⚡','⚡','⚡'],jackpot:['7','7','7']}[kind];
 let prize='';const materials=mult=>{const n=Math.round(stake*mult);p.cash+=n;return '+'+n+' materials'};
 const upgrade=()=>{const owned=Object.keys(p.gear||{}).filter(id=>loot[id]&&p.gear[id]<5);if(!owned.length)return materials(2);const id=pick(owned),before=p.gear[id];p.gear[id]=Math.min(5,before+levelGain);return loot[id].name+' upgraded: LV '+before+' → '+p.gear[id]};
 const weapon=()=>{const pool=Object.keys(loot).filter(id=>loot[id].type==='weapon'&&!p.gear?.[id]&&(!loot[id].fusion||(p.unlocked||[]).includes(id)));const used=Object.keys(p.gear||{}).filter(id=>loot[id]?.type==='weapon').length;if(used>=capacity('weapon')||!pool.length)return upgrade();const id=pick(pool);p.gear[id]=tier>=2?2:1;const base=p.char==='arsenal'||p.char?.id==='arsenal'?6:p.char==='trailkeeper'||p.char?.id==='trailkeeper'?4:3;if(used>=base)(p.weaponPremium||(p.weaponPremium={}))[id]=true;return loot[id].name+' awarded · LV '+p.gear[id]};
 const buff=()=>{const id=pick(['damage','haste','magnet']),strength=(gambler?2:1)*(1+tier*.25);if(id==='damage'){const n=.04*strength;p.gambleDamage=(p.gambleDamage||0)+n;return '+'+Math.round(n*100)+'% damage this run'}if(id==='haste'){const n=.04*strength;p.slotHaste=(p.slotHaste||0)+n;return '+'+Math.round(n*100)+'% attack speed this run'}const n=20*strength;p.slotMagnet=(p.slotMagnet||0)+n;return '+'+n+' pickup range this run'};
 if(kind==='bust')prize='No match this time';if(kind==='materials')prize=materials(1.5);if(kind==='upgrade')prize=upgrade();if(kind==='weapon')prize=weapon();if(kind==='buff')prize=buff();if(kind==='jackpot')prize=materials(5)+' · '+upgrade()+' · '+buff();
 const refund=gambler?Math.max(1,Math.floor(cost*(.10+random()*.20))):0;if(refund){p.cash+=refund;prize+=' · +'+refund+' materials cashback'};p.slotKind=kind;p.gambleResult=kind.toUpperCase()+' · '+prize+' (spin cost '+cost+')';return true;
}
function gamblePanel(p,w,gambler,disabled=false){const cost=gamblePrice(p,w,gambler),reels=p.slotReels||['7','7','7'];return `<section style="margin:18px 0;padding:18px;border:2px solid #e8c267;border-radius:16px;background:linear-gradient(145deg,#35273c,#151c2d);box-shadow:inset 0 0 30px #e5aa2015"><style>@keyframes overfusedSlot{0%{transform:translateY(-12px);filter:blur(4px)}20%{transform:translateY(12px)}40%{transform:translateY(-12px)}60%{transform:translateY(10px);filter:blur(3px)}80%{transform:translateY(-6px)}100%{transform:translateY(0);filter:blur(0)}}</style><strong style="color:#ffe29b;letter-spacing:2px">🎰 OVERFUSED SLOTS</strong><small style="display:block;margin-top:6px">${5-(p.gambles||0)} SPINS LEFT THIS SHOP ${gambler?'· GAMBLER ADVANTAGE':''}</small><div style="display:flex;justify-content:center;gap:10px;margin:16px 0">${reels.map((symbol,i)=>`<div style="display:grid;place-items:center;width:78px;height:86px;border:3px solid #bba061;border-radius:10px;background:#f4ebce;color:#452c48;font:bold 42px monospace;overflow:hidden"><span style="${p.slotReels?'animation:overfusedSlot '+(.65+i*.2)+'s ease-out;':''}">${symbol}</span></div>`).join('')}</div><div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center">${SLOT_STAKES.map(stake=>`<button data-stake="${stake}" style="${stake===selectedSlotStake?'background:#e6c26f;color:#241e2c;border-color:#ffe9a3':''}" ${disabled?'disabled':''}>✦ ${stake}</button>`).join('')}</div><p style="font-size:12px">Choose your wager. Higher wagers improve upgrade levels and buff strength. ${gambler?'You pay 25% less; buff prizes are twice as strong. Every spin returns 10–30% of its cost in materials, even on a loss.':''}</p><button id="gamble" ${(disabled||(p.gambles||0)>=5||p.cash<cost)?'disabled':''} style="display:block;margin:auto;background:#e6c26f;color:#241e2c;font-weight:bold">SPIN · PAY ✦ ${cost}</button><p role="status" style="color:#ffe6ad;font-weight:bold">${p.gambleResult||'Match three symbols to claim your prize.'}</p><details><summary>Prize table & odds</summary><p>✦ Materials: 1.5× wager · ⬆ Upgrade gear · ⚔ New weapon · ⚡ Damage / attack speed / pickup buff · 777 Jackpot: 5× materials + upgrade + buff. Full weapon inventory? The weapon prize becomes an upgrade. Maxed loadout? Upgrade prizes become 2× materials.</p><p>Odds (no match / materials / upgrade / weapon / buff / jackpot): ${gambler?'15% / 30% / 20% / 15% / 12% / 8%':'35% / 30% / 15% / 10% / 8% / 2%'}. New weapons require a free slot. Prizes and buffs last for this run.</p></details>${p.gambleDamage||p.slotHaste||p.slotMagnet?`<small>SLOT BUFFS: +${Math.round((p.gambleDamage||0)*100)}% DAMAGE · +${Math.round((p.slotHaste||0)*100)}% ATTACK SPEED · +${p.slotMagnet||0} PICKUP RANGE</small>`:''}</section>`}

