function achievementValue(a){return a.key==='endless'?extraProgress.endless:profile[a.key]||0}
function checkAchievements(){let changed=false;for(const a of achievements)if(!earnedAchievements.includes(a.id)&&achievementValue(a)>=a.goal){earnedAchievements.push(a.id);changed=true;showToast('Achievement: '+a.name)}if(changed)saveExtras()}
