function utility(kind){if(state==='playing')pause();$('#utility')?.remove();const el=document.createElement('div');el.id='utility';el.innerHTML=`<section class="utility-panel"><button id="utility-close" class="close">✕</button>${kind==='cheats'?`<div class="eyebrow">SECRET SHORTCUTS</div><h2>Cheat codes</h2><p>Unlock survivors anytime. Run buffs need an active run. Using a code disables achievements and quest progress for that run. Playing a survivor unlocked only by a code also disables earned progress.</p><form id="code-form"><input id="code-input" autocomplete="off" placeholder="Enter code" aria-label="Cheat code"><button class="primary">REDEEM</button></form><p id="code-result" role="status"></p><button id="clear-codes">REMOVE ALL CODES</button><p class="hint">Clears code unlocks and active buffs. Materials already gained or spent and healing already received stay. This run remains ineligible for achievements.</p><details><summary>Show codes</summary><p>ALLSTARS — unlock every survivor<br>FORGE — unlock Forgemaster<br>ASCEND — unlock Ascendant<br>MEDIC — unlock Medic<br>RICH — add 500 materials<br>POWERUP — +50% damage for this run<br>HASTE — +50% attack speed for this run<br>HEAL — fully restore health<br>IRONMAN — +100 max HP for this run</p></details>`:`<div class="eyebrow">YOUR TROPHY CASE</div><h2>Achievements</h2><p>${earnedAchievements.length} / ${achievements.length} earned · Progress saves on this browser.</p><div class="achievement-list">${achievements.map(a=>`<div class="achievement ${earnedAchievements.includes(a.id)?'earned':''}"><strong>${earnedAchievements.includes(a.id)?'★':'◇'} ${a.name}</strong><p>${a.desc}</p><small>${Math.min(achievementValue(a),a.goal)} / ${a.goal}</small></div>`).join('')}</div>`}</section>`;document.body.appendChild(el);resetInput();$('#utility-close').onclick=()=>{el.remove();if(state==='paused')pause();else if(state==='character')choose()};if(kind==='cheats')$('#clear-codes').onclick=()=>{$('#code-result').textContent=removeCodes()};if(kind==='cheats')$('#code-form').onsubmit=e=>{e.preventDefault();$('#code-result').textContent=redeemCode($('#code-input').value)}}
function removeCodes(){soloAscendActive=false;cheatUnlocks=[];saveExtras();if(run){run.cheats={};run.maxHp=maxHp();run.hp=Math.min(run.hp,run.maxHp);updateHud();if(state==='shop')renderShop()}return 'All code unlocks and active buffs removed. Earned survivor unlocks are kept.'}
function redeemCode(value){const code=value.trim().toUpperCase(),single={FORGE:'forgemaster',ASCEND:'ascendant',MEDIC:'medic'};if(code==='ALLSTARS'||single[code]){if(run&&['paused','playing','shop'].includes(state))run.cheated=true;if(code==='ASCEND')soloAscendActive=true;const ids=code==='ALLSTARS'?characters.map(c=>c.id):[single[code]];cheatUnlocks=[...new Set([...cheatUnlocks,...ids])];saveExtras();return code==='ALLSTARS'?'All survivors unlocked!':characters.find(c=>c.id===single[code]).name+' unlocked!'}if(!['RICH','POWERUP','HASTE','HEAL','IRONMAN'].includes(code))return 'Unknown code. Check the code list below.';if(!run||!['paused','playing','shop'].includes(state))return 'Start a run before using this buff.';run.cheats=run.cheats||{};run.cheated=true;if(code==='RICH')run.cash+=500;if(code==='HEAL')run.hp=run.maxHp;if(['POWERUP','HASTE','IRONMAN'].includes(code)){if(run.cheats[code])return 'This buff is already active for this run.';run.cheats[code]=true;if(code==='IRONMAN'){run.maxHp=maxHp();run.hp=Math.min(run.maxHp,run.hp+100)}}updateHud();if(state==='shop')renderShop();return {RICH:'+500 materials!',HEAL:'Health fully restored!',POWERUP:'+50% damage for this run!',HASTE:'+50% attack speed for this run!',IRONMAN:'+100 maximum health for this run!'}[code]}
function isUnlocked(c){return cheatUnlocks.includes(c.id)||!c.quest||profile[c.quest.key]>=c.quest.target}
function saveProfile(){try{localStorage.setItem('lucky-quests',JSON.stringify(profile));localStorage.setItem('lucky-champions',JSON.stringify(championWins));progressDirty=false}catch{}}
function progress(key,n=1){if(run?.cheated)return;const locked=characters.filter(c=>!isUnlocked(c));profile[key]=key==='wave'?Math.max(profile[key],n):profile[key]+n;progressDirty=true;for(const c of locked)if(isUnlocked(c)&&!newUnlocks.includes(c.name))newUnlocks.push(c.name);checkAchievements();if(key!=='kills')saveProfile()}
