function showFusionGuide(){const el=document.createElement('div');el.id='utility';el.innerHTML=`<section class="utility-panel"><button id="guide-close" class="close" aria-label="Close fusion guide">✕</button><div class="eyebrow">THE OVERFUSED RECIPE BOOK</div><h2>Fusion Guide</h2><p>Upgrade both ingredients to level 5, then pay the listed fee to combine them in the shop’s Fusion Lab. Ingredients are consumed. Fusions enter your shop pool and can upgrade to level 5 too. Weapon + item recipes can create an attacking item that uses only an item slot. Trail upgrades increase radius, damage, duration, and drop speed.</p><div class="fusion-guide-list">${recipes.map(([a,b,out])=>`<article class="guide-recipe"><div class="guide-ingredients"><span style="color:${gear[a].color}">${gear[a].icon} ${gear[a].name}<small>LEVEL 5</small></span><b>+</b><span style="color:${gear[b].color}">${gear[b].icon} ${gear[b].name}<small>LEVEL 5</small></span></div><div class="guide-result"><strong style="color:${gear[out].color}">→ ${gear[out].icon} ${gear[out].name}</strong><p>${gear[out].desc}</p></div></article>`).join('')}</div><p class="hint">Cataclysm Trail, Starforge, and Worldheart combine two maxed fusions. Item fusions use one item slot and keep both ingredients’ max-level bonuses at level 1. Forgemaster-created fusions start at level 2 or 3.</p></section>`;document.body.appendChild(el);$('#guide-close').onclick=()=>el.remove()}
function title(){$('#panel').classList.remove('shop-panel');state='title';overlay(`<div class="eyebrow">AN RNG ARENA ROGUELITE</div><h1><em>OVERFUSED.</em></h1><p>Fight. Shop. Upgrade. Fuse.<br>Face the wave-5 miniboss and a random wave-10 boss.</p><div class="intro-grid"><span>${Object.values(gear).filter(g=>g.type==='weapon'&&!g.fusion).length} WEAPONS</span><span>${Object.values(gear).filter(g=>g.type==='item').length} ITEMS</span><span>${recipes.length} FUSIONS</span></div><button class="primary" id="start">CHOOSE YOUR SURVIVOR →</button><p><button id="coop-launch" class="primary">ONLINE CO-OP · UP TO 4 PLAYERS</button></p><p><button id="fusion-guide">⚗ FUSION GUIDE</button><button id="boss-guide">♛ BOSS ROSTER</button></p><p class="hint">Move with WASD / arrows or drag the arena on mobile.<br>Weapons fire automatically. Space or tap DASH to escape.</p>${best?`<small>BEST RUN · WAVE ${best}</small>`:''}`);$('#coop-launch').onclick=()=>{location.href='https://overfused-coop.onrender.com/#earnedRoster='+characters.filter(c=>!c.quest||(profile[c.quest.key]||0)>=c.quest.target).map(c=>c.id).join(',')+(soloAscendActive?'&ascend=1':'')};$('#start').onclick=choose;$('#fusion-guide').onclick=showFusionGuide;$('#boss-guide').onclick=()=>{overlay(bossGuideMarkup());$('#panel').classList.add('shop-panel');paintBossGuide();$('#boss-back').onclick=title}}
